# Count YES results by company
booking_issue_counts = Counter()
for d, result in zip(candidates, all_results):
    if 'YES' in result.upper():
        booking_issue_counts[d['company_id']] += 1

print("Flight booking issue complaints by company:")
for company, count in booking_issue_counts.most_common():
    print(f"  {company}: {count}")

print("\n\nTotal YES:", sum(booking_issue_counts.values()))
print("Total NO:", len(all_results) - sum(booking_issue_counts.values()))
